// builds edits_H.json (x_pals, x_fire, x_boss) from the new line sets below; old lines are parsed from packet_H.md
// Flow: A open -> B reply (>P.r) -> [C join (P.r>P.j) -> D join (P.j>P.j2)] -> A|B answer the last joiner (P.j|P.j2 > P.end) -> A close (P.r or P.end)
const fs = require('fs'), path = require('path');
const dir = __dirname;
const pk = fs.readFileSync(path.join(dir, 'packet_H.md'), 'utf8').split(/\r?\n/);
const old = {}; let cur = null;
for (const l of pk) {
  const h = /^### ([HM]) @(\S+)/.exec(l); if (h) { cur = h[1] + ':' + h[2]; old[cur] = []; continue; }
  if (cur && /^\d+ \| /.test(l)) { const parts = l.split(' | '); old[cur].push(parts[1].trim()); }
  else if (l.startsWith('#')) cur = null;
}
