let bad = 0;
const tiers = mk => { const m = /^~(\d+) /.exec(mk); return m ? m[1].split('').map(Number) : [1, 2, 3]; };
const thr = mk => mk.replace(/^~\d+ /, '').slice(1);
const ans = mk => thr(mk).split('>')[0].split('|'), nxt = mk => thr(mk).split('>')[1];
const all = []; for (const k in N) for (const x of N[k]) all.push([k, ...x]);
const SC = { pals: ['пр'], fire: ['вг'], xboss: ['бс'] };
for (const sc in SC) {
  const t = SC[sc][0];
  const L = (w, s) => N[`${w}:${w === 'H' ? 'хх' : 'мх'}_${s}`];
  const jr = w => N[`${w}:${w === 'H' ? 'хх' : 'мх'}_до_того_хто_встряв`].filter(x => thr(x[0]).startsWith(sc + '.'));
  const st = { open: w => L(w, t), reply: w => L(w, t + '_відповідь'), join: w => L(w, t + '_встряє'), jr, close: w => L(w, t + '_кінець') };
  const need = (step, thread, why) => { for (const w of ['H', 'M']) for (const tr of [1, 2, 3]) { const n = st[step](w).filter(x => ans(x[0]).includes(thread) && tiers(x[0]).includes(tr)).length; if (n < 2) { bad++; console.log('SHORT', sc, step, w, '~' + tr, thread, n, why); } } };
  const opens = new Set([...st.open('H'), ...st.open('M')].map(x => thr(x[0])));
  for (const o of opens) need('reply', o, 'after open');
  const rN = new Set([...st.reply('H'), ...st.reply('M')].map(x => nxt(x[0])));
  for (const r of rN) { need('close', r, 'after reply'); }
  const joins = [...st.join('H'), ...st.join('M')];
  // C joins on a reply target; D joins on a C target
  const reach = new Set(rN); let grew = true; const jT = new Set();
  while (grew) { grew = false; for (const x of joins) if (ans(x[0]).some(a => reach.has(a))) { const n = nxt(x[0]); if (!jT.has(n)) { jT.add(n); grew = true; } if (!reach.has(n)) reach.add(n); } }
  for (const r of rN) need('join', r, 'C after reply');
  for (const j of jT) { need('jr', j, 'answer the joiner'); }
  const eN = new Set([...st.jr('H'), ...st.jr('M')].map(x => nxt(x[0])));
  for (const e of eN) need('close', e, 'after answer to joiner');
  for (const x of all) if (!thr(x[1 - 1 + 1]).startsWith) {}
  // every line on a reachable thread
  const known = new Set([...opens, ...rN, ...jT, ...eN]);
  for (const step of ['reply', 'join', 'jr', 'close']) for (const w of ['H', 'M']) for (const x of st[step](w)) if (!ans(x[0]).every(a => known.has(a))) { bad++; console.log('ORPHAN', sc, step, w, x[0]); }
  for (const w of ['H', 'M']) for (const x of st.close(w).concat(st.jr(w))) if (/\?\s*$/.test(x[1]) && step !== 'x') { /* questions */ }
}
// no questions at the end of closes and answers to joiners and replies; swears; prefixes; gender forms
const sw = /(бля|курв|сук|нахуй|нахуя|хуй|хуя|хулі|пизд|піздж|спизд|їба|їбал|охуї|срак|сран|всрав|всрався|падл|гівн|бляха|ссикл|лошар)/gi;
for (const k in N) {
  const [who, list] = k.split(':');
  for (const [mk, uk, en] of N[k]) {
    if (!/^(~\d+ )?\^(pals|fire|xboss)\.[^\s]+$/.test(mk)) { bad++; console.log('MARK', k, mk); }
    if (/(_відповідь|_кінець|_до_того)/.test(list) && /\?\s*$/.test(uk)) { bad++; console.log('QUESTION at', list, uk); }
    if (/\?\s*$/.test(uk) !== /\?\s*$/.test(en)) console.log('note ?-mismatch', uk, '|', en);
    if (who === 'M') { const m = uk.match(sw) || []; if (m.length > 2) { bad++; console.log('SWEARS', m.length, uk); } }
    if (who === 'H' && /(бля|курв|сук|(^|[^а-яіїє])хуй|пизд)/i.test(uk)) { bad++; console.log('HUGIN SWEARS', uk); }
    for (const g of uk.matchAll(/\{([^{}]*\|[^{}]*)\}/g)) { const [a, b] = g[1].replace(/^>/, '').split('|'); if (a && b && a[0] === b[0]) { bad++; console.log('SPLIT', uk); } }
  }
}
